/* Live demo on the landing page: a sample card index with invented records.
 * Search, open a card, add or change a record. Everything lives in the page memory only:
 * no network, no storage; reloading the page restores the original sample.
 * The section skeleton (#demo, title, label) is generated by scripts/generate-docs.cjs; this file builds the controls. */
(function () {
  'use strict';
  var root = document.getElementById('demo');
  if (!root || root.getAttribute('data-demo') !== 'kartoteka') return;
  var body = root.querySelector('.ppk-demo-body');
  if (!body) return;

  var lang = (document.documentElement.lang || 'de').slice(0, 2);
  var TEXT = {
    de: { table: 'Tabelle', tableName: 'Kontakte', search: 'Datensätze durchsuchen', newRecord: 'Neuer Datensatz', reset: 'Beispiel zurücksetzen',
          fields: ['Nachname', 'Vorname', 'Vatersname', 'Geburtsdatum', 'Telefon', 'Notiz'], required: 'Pflichtfeld',
          save: 'Speichern', cancel: 'Abbrechen', card: 'Karte', cardNew: 'Neuer Datensatz', idNew: 'neu', list: 'Datensätze',
          none: 'Keine Treffer.', needed: 'Nachname und Vorname sind Pflichtfelder.', saved: 'Gespeichert — nur im Speicher dieser Seite.',
          added: 'Datensatz hinzugefügt — nur im Speicher dieser Seite.', resetDone: 'Beispiel zurückgesetzt.', hint: 'Wählen Sie einen Datensatz oder legen Sie einen neuen an.',
          count: function (n) { return n + (n === 1 ? ' Datensatz' : ' Datensätze'); } },
    en: { table: 'Table', tableName: 'Contacts', search: 'Search records', newRecord: 'New record', reset: 'Reset sample',
          fields: ['Last name', 'First name', 'Patronymic', 'Date of birth', 'Phone', 'Note'], required: 'required',
          save: 'Save', cancel: 'Cancel', card: 'Card', cardNew: 'New record', idNew: 'new', list: 'Records',
          none: 'Nothing found.', needed: 'Last name and first name are required.', saved: 'Saved — in this page’s memory only.',
          added: 'Record added — in this page’s memory only.', resetDone: 'Sample reset.', hint: 'Pick a record or create a new one.',
          count: function (n) { return n + (n === 1 ? ' record' : ' records'); } },
    ru: { table: 'Таблица', tableName: 'Контакты', search: 'Поиск по записям', newRecord: 'Новая запись', reset: 'Сбросить пример',
          fields: ['Фамилия', 'Имя', 'Отчество', 'Дата рождения', 'Телефон', 'Заметка'], required: 'обязательно',
          save: 'Сохранить', cancel: 'Отмена', card: 'Карточка', cardNew: 'Новая запись', idNew: 'новая', list: 'Записи',
          none: 'Ничего не найдено.', needed: 'Фамилия и имя обязательны.', saved: 'Сохранено — только в памяти этой страницы.',
          added: 'Запись добавлена — только в памяти этой страницы.', resetDone: 'Пример сброшен.', hint: 'Выберите запись или создайте новую.',
          count: function (n) {
            var m10 = n % 10, m100 = n % 100;
            var w = (m10 === 1 && m100 !== 11) ? ' запись' : (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) ? ' записи' : ' записей';
            return n + w;
          } }
  };
  var T = TEXT[lang] || TEXT.de;

  /* invented records, same fields as the real "Kontakte" table: last name, first name, patronymic, date of birth, phone, note */
  var SAMPLE = [
    ['Becker', 'Lena', '', '1998-03-14', '+00 555 0101', ''],
    ['Schneider', 'Jonas', '', '1997-11-02', '+00 555 0102', ''],
    ['Hoffmann', 'Mira', '', '1999-07-21', '+00 555 0103', ''],
    ['Wagner', 'Paul', '', '1998-01-30', '+00 555 0104', ''],
    ['Keller', 'Sofia', '', '1996-09-09', '+00 555 0105', ''],
    ['Brandt', 'Tim', '', '1999-05-18', '+00 555 0106', ''],
    ['Vogel', 'Nora', '', '1997-12-25', '+00 555 0107', ''],
    ['Richter', 'Anna', '', '1998-04-12', '+00 555 0108', '']
  ];
  var INPUT_TYPES = ['text', 'text', 'text', 'date', 'tel', 'textarea'];
  var records, nextId, query = '', editing = null;

  function loadSample() {
    records = SAMPLE.map(function (r, i) { return { id: i + 1, v: r.slice() }; });
    nextId = records.length + 1;
    query = '';
    editing = null;
  }
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  /* ---- skeleton ---- */
  body.textContent = '';
  var side = el('div', 'ppk-demo-side');
  var main = el('div', 'ppk-demo-main');
  var tableField = el('div', 'ppk-field');
  tableField.appendChild(el('small', null, T.table));
  tableField.appendChild(document.createTextNode(T.tableName));
  var searchLabel = el('label', 'ppk-field');
  searchLabel.appendChild(el('small', null, T.search));
  var searchInput = el('input', 'demo-input');
  searchInput.type = 'search';
  searchInput.autocomplete = 'off';
  searchLabel.appendChild(searchInput);
  var newBtn = el('button', 'ppk-btn ppk-btn-primary', T.newRecord);
  newBtn.type = 'button';
  var resetBtn = el('button', 'ppk-btn', T.reset);
  resetBtn.type = 'button';
  side.appendChild(tableField);
  side.appendChild(searchLabel);
  side.appendChild(newBtn);
  side.appendChild(resetBtn);

  var count = el('p', 'demo-count');
  var view = el('div', 'demo-view');
  var msg = el('div', 'ppk-demo-empty', T.hint);
  msg.setAttribute('role', 'status');
  msg.setAttribute('aria-live', 'polite');
  main.appendChild(count);
  main.appendChild(view);
  main.appendChild(msg);
  body.appendChild(side);
  body.appendChild(main);

  function say(text, done) {
    msg.className = 'ppk-demo-empty' + (done ? ' ppk-demo-done' : '');
    msg.textContent = text;
  }

  /* ---- list view ---- */
  function matches(r) {
    if (!query) return true;
    var q = query.toLowerCase();
    return (String(r.id) + ' ' + r.v.join(' ')).toLowerCase().indexOf(q) !== -1;
  }
  function renderList(focusId) {
    editing = null;
    view.textContent = '';
    var shown = records.filter(matches);
    count.textContent = T.count(shown.length);
    if (!shown.length) {
      view.appendChild(el('p', 'ppk-demo-empty', T.none));
      return;
    }
    var ul = el('ul', 'ppk-rows');
    ul.setAttribute('aria-label', T.list);
    shown.forEach(function (r) {
      var li = el('li');
      var open = el('button', 'demo-open', r.v[0] + ', ' + r.v[1]);
      open.type = 'button';
      open.setAttribute('data-id', String(r.id));
      if (r.v[4]) open.appendChild(el('small', null, ' · ' + r.v[4]));
      open.addEventListener('click', function () { openCard(r.id); });
      li.appendChild(open);
      li.appendChild(el('span', 'ppk-badge', '#' + r.id));
      ul.appendChild(li);
    });
    view.appendChild(ul);
    if (focusId != null) {
      var b = ul.querySelector('[data-id="' + focusId + '"]');
      if (b) b.focus();
    }
  }

  /* ---- card view ---- */
  function openCard(id) {
    var rec = id == null ? null : records.filter(function (r) { return r.id === id; })[0];
    editing = rec ? rec.id : 0;
    view.textContent = '';
    count.textContent = T.card + ' · ' + (rec ? '#' + rec.id : T.cardNew);
    var form = el('form', 'demo-card');
    form.noValidate = true;
    var inputs = [];
    T.fields.forEach(function (label, i) {
      var wrap = el('label', 'demo-fld');
      var req = i < 2;
      wrap.appendChild(el('span', null, label + (req ? ' *' : '')));
      var inp = INPUT_TYPES[i] === 'textarea' ? el('textarea', 'demo-input') : el('input', 'demo-input');
      if (inp.tagName === 'INPUT') inp.type = INPUT_TYPES[i];
      else inp.rows = 2;
      inp.value = rec ? rec.v[i] : '';
      inp.autocomplete = 'off';
      if (req) inp.setAttribute('aria-required', 'true');
      wrap.appendChild(inp);
      form.appendChild(wrap);
      inputs.push(inp);
    });
    var err = el('p', 'demo-error');
    err.setAttribute('role', 'alert');
    form.appendChild(err);
    var actions = el('div', 'demo-actions');
    var save = el('button', 'ppk-btn ppk-btn-primary', T.save);
    save.type = 'submit';
    var cancel = el('button', 'ppk-btn', T.cancel);
    cancel.type = 'button';
    actions.appendChild(save);
    actions.appendChild(cancel);
    form.appendChild(actions);
    view.appendChild(form);
    say(T.hint);

    cancel.addEventListener('click', function () {
      var back = rec ? rec.id : null;
      say(T.hint);
      renderList(back);
      if (back == null) newBtn.focus();
    });
    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var vals = inputs.map(function (i) { return i.value.trim(); });
      var bad = [0, 1].filter(function (i) { return !vals[i]; });
      inputs.forEach(function (inp, i) { inp.setAttribute('aria-invalid', bad.indexOf(i) !== -1 ? 'true' : 'false'); });
      if (bad.length) {
        err.textContent = T.needed;
        inputs[bad[0]].focus();
        return;
      }
      var focusId;
      if (rec) {
        rec.v = vals;
        focusId = rec.id;
        query = query && !matches(rec) ? '' : query;
        say(T.saved, true);
      } else {
        var added = { id: nextId++, v: vals };
        records.push(added);
        query = '';
        focusId = added.id;
        say(T.added, true);
      }
      searchInput.value = query;
      renderList(focusId);
    });
    inputs[0].focus();
  }

  /* ---- wiring ---- */
  searchInput.addEventListener('input', function () {
    query = searchInput.value.trim();
    renderList();
    say(T.hint);
  });
  newBtn.addEventListener('click', function () { openCard(null); });
  resetBtn.addEventListener('click', function () {
    loadSample();
    searchInput.value = '';
    renderList();
    say(T.resetDone, true);
  });

  loadSample();
  renderList();
})();
